/**
 * Serializer for creating orders from cart (dual-flow payment architecture).
 *
 * The flow follows the pay way's ``settlement``:
 * 1. ``online``: the shopper pays at checkout. A client-confirmed
 * provider (Stripe) takes ``payment_intent_id`` for the balance
 * left after deductions (gift cards, promotions, loyalty points);
 * without one the order is created order-first, which succeeds only
 * when the deductions cover the whole total, so no provider charge
 * is made. A hosted-checkout provider (Viva) creates the order
 * first and redirects.
 * 2. Any other settlement (courier cash, carrier terminal, offline
 * transfer): money is collected later, no ``payment_intent_id``.
 *
 * The order is created from an existing cart identified via X-Cart-Id header.
 * Cart is NOT sent in request body - it's retrieved from the header using CartService.
 */
export type OrderCreateFromCartRequest = {
  /**
     * Payment method ID
     */
  payWayId: number
  /**
     * Payment intent ID from payment provider (required for online payments)
     */
  paymentIntentId?: string | null
  /**
     * Customer first name
     */
  firstName: string
  /**
     * Customer last name
     */
  lastName: string
  /**
     * Customer email address
     */
  email: string
  /**
     * Street name
     */
  street: string
  /**
     * Street number
     */
  streetNumber: string
  /**
     * City name
     */
  city: string
  /**
     * Postal/ZIP code. Must match the country's ``postal_code_pattern``; stored normalised (trimmed, upper-case, single spaces).
     */
  zipcode: string
  /**
     * Country alpha-2 code (e.g., 'GR', 'US')
     */
  countryId: string
  /**
     * Region alpha code
     */
  regionId?: string | null
  /**
     * Customer phone number
     */
  phone: string
  /**
     * Customer notes or special instructions
     */
  customerNotes?: string
  /**
     * Floor, as a FloorChoicesEnum member (e.g. FIRST_FLOOR)
     *
     * * `BASEMENT` - Basement
     * * `GROUND_FLOOR` - Ground Floor
     * * `FIRST_FLOOR` - First Floor
     * * `SECOND_FLOOR` - Second Floor
     * * `THIRD_FLOOR` - Third Floor
     * * `FOURTH_FLOOR` - Fourth Floor
     * * `FIFTH_FLOOR` - Fifth Floor
     * * `SIXTH_FLOOR_PLUS` - Sixth Floor Plus
     */
  floor?: FloorEnum | BlankEnum
  /**
     * Location, as a LocationChoicesEnum member (e.g. HOME)
     *
     * * `HOME` - Home
     * * `OFFICE` - Office
     * * `OTHER` - Other
     */
  locationType?: LocationTypeEnum | BlankEnum
  /**
     * Buyer tax number (ΑΦΜ). Required when ``document_type`` is INVOICE; 9 digits for Greek ΑΦΜ, leading EL/GR prefix is stripped automatically.
     */
  billingVatId?: string
  /**
     * ISO 3166-1 alpha-2 country code for the buyer's tax identity. Defaults to the order country when blank.
     */
  billingCountry?: string
  /**
     * RECEIPT (Α.Λ.Π., Tier A — retail) or INVOICE (Τιμολόγιο Πώλησης, Tier B — B2B). Selecting INVOICE requires a valid ``billing_vat_id``.
     *
     * * `RECEIPT` - Receipt
     * * `INVOICE` - Invoice
     */
  documentType?: OrderCreateDocumentType
  /**
     * Company legal name (Επωνυμία) for the invoice
     */
  billingCompanyName?: string
  /**
     * Company tax office (ΔΟΥ)
     */
  billingTaxOffice?: string
  /**
     * Company business activity (Δραστηριότητα)
     */
  billingActivity?: string
  /**
     * Company registered address street — blank copies the shipping street on INVOICE orders
     */
  billingStreet?: string
  billingStreetNumber?: string
  billingCity?: string
  billingZipcode?: string
  /**
     * Number of loyalty points to redeem for discount on this order
     */
  loyaltyPointsToRedeem?: number | null
  /**
     * Gift card codes to redeem against this order (max 3). When they cover the full total, omit payment_intent_id — no provider charge happens at all.
     */
  giftCardCodes?: Array<string>
  /**
     * BoxNow APM locker ID from the widget
     */
  boxnowLockerId?: string
  /**
     * Carrier code from /api/v1/shipping/options (e.g. 'acs').
     */
  shippingProviderCode?: string | string
  /**
     * Generic fulfilment kind, independent of provider.
     *
     * * `home_delivery` - Home delivery
     * * `pickup_point` - Pickup point / locker
     */
  shippingKind?: ShippingKind
  /**
     * ACS Smartpoint / shop external ID (Phase 2 pickup-point flow).
     */
  acsStationExternalId?: string
  /**
     * ACS_Station_Branch_Destination value.
     */
  acsStationBranch?: string
  /**
     * Optional per-order ACS Charge_Type override. Leave unset to use the carrier-level default (COD on a COD-only contract). Setting this here only makes sense if the ACS commercial contract permits the chosen value — invalid combinations are rejected by ACS_Create_Voucher.
     *
     * * `1` - Prepaid
     * * `2` - Cash on delivery
     */
  acsChargeType?: AcsChargeType
  /**
     * Optional per-order override for ACS Item_Quantity (number of physical parcels in the shipment). Defaults to 1. Must NOT be set for Smartpoint pickup — ACS rejects multipart vouchers on lockers.
     */
  acsItemQuantity?: number
}

export type OrderDeliveryMethod = {
  providerCode: string | null
  providerName: string | null
  kind: ShippingKind
}

export type OrderDetail = {
  readonly id: number
  user?: number | null
  /**
     * Country Code Alpha 2
     */
  country: string | null
  /**
     * Region Code
     */
  region: string | null
  floor?: FloorEnum | BlankEnum
  locationType?: LocationTypeEnum | BlankEnum
  street: string
  streetNumber: string
  payWay: number | null
  status?: OrderStatus
  /**
     * Label for ``status``, rendered by the frontend instead of the raw enum value. In the request's language: ``X-Language``, then ``X-Locale``, then ``Accept-Language``, falling back to the default language (``core.middleware.locale.RequestLanguageMiddleware``).
     */
  readonly statusDisplay: string
  readonly statusUpdatedAt: string | null
  firstName: string
  lastName: string
  email: string
  zipcode: string
  place?: string
  city: string
  readonly phone: string
  customerNotes?: string
  readonly amountDue: number
  items: Array<OrderItemDetail>
  readonly shippingPrice: number
  readonly paymentMethodFee: number
  documentType?: OrderDocumentType
  /**
     * Buyer's tax number (ΑΦΜ) — required when issuing an invoice (vs. a retail receipt). 9 digits for Greek ΑΦΜ, no ``EL`` / ``GR`` prefix.
     */
  readonly billingVatId: string
  /**
     * ISO 3166-1 alpha-2 country code of the buyer for tax purposes. Pairs with ``billing_vat_id``; determines which AADE invoice type (1.1 domestic, 1.2 intra-EU, 1.3 third-country) applies.
     */
  readonly billingCountry: string
  readonly billingCompanyName: string
  /**
     * Billing Tax Office (ΔΟΥ)
     */
  readonly billingTaxOffice: string
  /**
     * Billing Business Activity
     */
  readonly billingActivity: string
  readonly billingStreet: string
  readonly billingStreetNumber: string
  readonly billingCity: string
  readonly billingZipcode: string
  readonly createdAt: string
  readonly updatedAt: string
  readonly uuid: string
  readonly totalPriceItems: number
  readonly totalPriceExtra: number
  /**
     * Promotion Discount
     *
     * Total discount granted by promotions/coupons, snapshotted at order creation. Breakdown lives in metadata['promotions'] + PromotionRedemption rows. Deducted by calculate_order_total_amount().
     */
  readonly discountAmount: number
  /**
     * Amount deducted from the order total in exchange for loyalty points. Deducted by calculate_order_total_amount().
     */
  readonly loyaltyDiscount: number
  /**
     * Portion of the order settled by gift-card balance. A payment, not a discount — it never reduces the taxable order value, only what the payment provider charges.
     */
  readonly giftCardAmount: number
  readonly fullAddress: string
  paymentId?: string | null
  paymentStatus?: PaymentStatusEnum | BlankEnum
  /**
     * Label for ``payment_status`` (mirrors ``status_display``), rendered by the frontend instead of the raw enum value. In the request's language: ``X-Language``, then ``X-Locale``, then ``Accept-Language``, falling back to the default language (``core.middleware.locale.RequestLanguageMiddleware``).
     */
  readonly paymentStatusDisplay: string
  /**
     * Payment Gateway
     */
  paymentMethod?: string
  /**
     * Which payment method the shopper chose, as the ``PayWayEnum`` key — the storefront's label for the order. Deliberately the KEY and not a rendered string: the storefront owns the label map for payment methods, so the key is stable across languages and the label follows the page. Snapshotted on the order, so it survives the PayWay row being deleted (``SET_NULL``) or its key renamed. EMPTY when the order has no pay way — ``allow_blank`` is load-bearing, without it the generated client schema rejects those orders outright.
     *
     * * `CREDIT_CARD` - Credit Card
     * * `PAY_ON_DELIVERY` - Pay On Delivery
     * * `BOX_NOW_PAY_ON_THE_GO` - BOX NOW PAY ON THE GO!
     * * `PAY_ON_STORE` - Pay On Store
     * * `PAY_PAL` - PayPal
     * * `STRIPE` - Stripe
     * * `BANK_TRANSFER` - Bank Transfer
     * * `APPLE_PAY` - Apple Pay
     * * `GOOGLE_PAY` - Google Pay
     * * `VIVA_WALLET` - Viva Wallet
     */
  payWayKey: PayWayKeyEnum | BlankEnum
  /**
     * True when the order's PayWay charges the shopper online (Stripe, Viva); false for cash-on-delivery / bank transfer. Surfaced on both list + detail so both views can suppress misleading 'outstanding amount' warnings for COD orders where the shopper intentionally paid €0 at checkout.
     */
  readonly isOnlinePayment: boolean
  /**
     * True when the carrier collects the money from the shopper rather than the store — cash or card to a courier at the door, OR paid to the carrier before pickup (BOX NOW Αντικαταβολή, marketed in English as PAY ON THE GO, which sends a payment link once the parcel reaches the locker). ``is_online_payment`` cannot answer this: it is false for bank transfer too, where the shopper pays us directly and nothing is owed on delivery. The storefront needs the distinction to show a collect-on-delivery order a green 'your order is placed, pay on delivery' panel instead of the amber 'payment is processing' warning, which would otherwise sit there for days (measured ACS remittance lag is ~4 days).
     */
  readonly isCollectedOnDelivery: boolean
  /**
     * How the order is delivered: the carrier (code and display name, null for a legacy order handled outside any provider) and the generic fulfilment kind (home delivery or pickup point). On the list too, so order history can label a row without opening it.
     */
  deliveryMethod: OrderDeliveryMethod
  /**
     * Whether the customer can cancel the order now: its status allows it and the courier has not yet taken the parcel. Read from local data, so the cancel request itself still asks the courier and can be refused with ``error.type`` ``parcel_with_courier``.
     */
  readonly canBeCanceled: boolean
  readonly isPaid: boolean
  /**
     * Where the shopper came from. Null for an order placed before attribution was recorded.
     */
  attribution: OrderAttribution | null
  /**
     * Order status timeline and history
     */
  readonly orderTimeline: Array<{
    changeType?: string
    timestamp?: string
    description?: string
    user?: string | null
  }>
  /**
     * Detailed pricing breakdown
     */
  readonly pricingBreakdown: {
    itemsSubtotal?: number
    shippingCost?: number
    paymentMethodFee?: number
    extrasTotal?: number
    discount?: number
    loyaltyDiscount?: number
    giftCardAmount?: number
    grandTotal?: number
    currency?: string
    amountDue?: number
    remainingAmount?: number
  }
  /**
     * Tracking and shipping details
     */
  readonly trackingDetails: {
    trackingNumber?: string | null
    shippingCarrier?: string | null
    hasTracking?: boolean
    estimatedDelivery?: string | null
    trackingUrl?: string | null
  } | null
  /**
     * True when the order has a retail receipt registered with AADE (myDATA) and its PDF, so the frontend can show the download CTA without asking the receipt endpoint. False while the receipt is pending, rejected or cancelled, and always for a store that issues its receipts outside the platform.
     */
  readonly hasInvoice: boolean
  /**
     * True when the storefront may offer the watermarked specimen receipt (``/order/{id}/specimen/download``): a demo store, for an order a receipt is issued for (shipped onwards). Always false on any other store.
     */
  readonly hasSpecimenReceipt: boolean
  /**
     * BoxNow shipment details when shipping_provider.code is 'boxnow', else null.
     */
  boxnowShipment: BoxNowShipmentDetail | null
  /**
     * ACS shipment details when the order's shipping provider is ACS, else null.
     */
  acsShipment: AcsShipmentDetail | null
  /**
     * Provider-agnostic shipment payload — frontends can read this single field instead of branching on boxnow_shipment / acs_shipment.  Returns the active provider's detail serializer dict (shape depends on the provider) or null when no shipment exists.
     */
  readonly shipment: {
    [key: string]: unknown
  } | null
  /**
     * Identifier of the carrier handling this order — 'acs', 'boxnow', or null when no provider is attached.  Lets frontends switch on a stable code instead of inspecting the shipment shape.
     */
  readonly shipmentProviderCode: string | null
  /**
     * Loyalty points this order earns its customer: the points actually awarded once the order has been credited, the projection before that. 0 when the program is off, the order has no account, or it was canceled or refunded.
     */
  readonly loyaltyPointsToEarn: number
  /**
     * Cancellation context for CANCELED orders — exposes the operator-supplied reason, timestamp, and shipment-cancel outcome from ``order.metadata['cancellation']``. Returns null when the order was not canceled. Internal flags from the metadata bag (webhook idempotency markers, mint tickets) are intentionally not surfaced.
     */
  readonly cancellation: {
    reason?: string
    canceledAt?: string
    previousStatus?: string
    shipmentCancel?: {
      attempted?: boolean
      dispatched?: boolean
      error?: string | null
    } | null
  } | null
  /**
     * Coupon codes redeemed on this order (empty when no coupon was used).
     */
  readonly appliedCouponCodes: Array<string>
  trackingNumber?: string
  shippingCarrier?: string
  readonly customerFullName: string
  readonly isCompleted: boolean
  readonly isCanceled: boolean
  /**
     * Meta Pixel ``eventID`` values the browser must reuse when firing the matching pixel call on the success page so Meta dedups the browser event against the server-side Conversions API event. Only the keys minted at order creation are surfaced (purchase, initiate_checkout, add_payment_info). Empty dict when the customer declined marketing cookies — in that case the browser should not fire the matching pixel either.
     */
  readonly metaEventIds: {
    [key: string]: string
  }
  /**
     * ISO 4217 currency code for every monetary field on the order (amountDue, shippingPrice, totalPriceItems, …). Surfaced as a top-level field because djmoney serialises money fields as bare numbers — without this, the frontend has no way to know whether ``59.98`` is EUR or USD, which breaks ad-pixel attribution and cart totals in multi-currency reports.
     */
  readonly currency: string
  /**
     * True when the customer (account, or email for a guest) has no earlier non-canceled order. Feeds the ``new_customer`` parameter of the Google Ads purchase conversion, which Google asks to be calculated rather than hardcoded.
     */
  readonly isFirstOrder: boolean
}

